826	    <button id="btn-grid" onclick="switchViewMode('grid')">🎨 网格</button>`;
827	
828	  html += `<input type="text" class="search-box" placeholder="🔍 搜索英雄..." oninput="doSearch(this.value)" style="margin-left:16px">`;
829	  controls.innerHTML = html;
830	}
831	
832	function buildNav() {
833	  const nav = document.getElementById("nav");
834	  if (!nav) return;
835	
836	  if (!gameData.hasLanes) {
837	    nav.style.display = "none";
838	    return;
839	  }
840	
841	  nav.style.display = "flex";
842	  nav.innerHTML = "";
843	  if (!gameData.lanes) return;
844	  Object.keys(gameData.lanes).forEach(lane => {
845	    const btn = document.createElement("button");
846	    btn.textContent = lane;
847	    btn.className = lane === currentLane ? "active" : "";
848	    btn.onclick = () => {
849	      currentLane = lane;
850	      switchView("lane");
851	    };
852	    nav.appendChild(btn);
853	  });
854	}
855	
856	// ============================================================
857	// 游戏切换
858	// ============================================================
859	async function switchGame(gameId) {
860	  // Update game selector buttons
861	  document.querySelectorAll(".game-selector button").forEach(b => {
862	    b.className = b.dataset.game === gameId ? "active" : "";
863	  });
864	
865	  // Load config
866	  const base = gameId === "lolm" ? "lolm" : "曙光英雄";
867	  const configResp = await fetch(base + "/config.json");
868	  if (!configResp.ok) throw new Error(`加载 ${gameId} 配置失败: ${configResp.status}`);
869	  gameConfig = await configResp.json();
870	
871	  // Reset state
872	  currentMethod = gameConfig.algorithm.type === "weighted" ? "weighted" : "zscore";
873	  currentView = "lane";
874	  currentLane = gameConfig.hasLanes ? gameConfig.lanes[0].name : null;
875	
876	  // Clear search box
877	  const searchBox = document.querySelector(".search-box");
878	  if (searchBox) searchBox.value = "";
879	
880	  // Load data
881	  document.getElementById("content").innerHTML =
882	    '<p style="text-align:center;padding:60px;color:#8b949e;">⏳ 加载中...</p>';
883	
884	  await loadGameData();
885	
886	  // Rebuild UI
887	  buildControls();
888	  buildNav();
889	  updateHeader();
890	  renderAll();
891	  updateFooter();
892	}
893	
894	function updateHeader() {
895	  const h1 = document.querySelector(".header h1");
896	  if (h1) h1.innerHTML = `${gameConfig.gameIcon} ${gameConfig.gameName} 英雄梯度排行榜`;
897	}
