    if (onlyInB.length > 0) html += `<span class="diff-positive">🆕 仅存在于 ${dateB} (新增): ${onlyInB.map(h => h.name).join('、')}</span>`;
    html += `</div>`;
  }

  // --- Diff Table ---
  html += `<div class="table-wrapper"><table class="compare-table"><thead><tr>
    <th onclick="sortCompareTable(this,0)">英雄 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,1)">${dateA} 梯度 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,2)">${dateB} 梯度 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,3)">评分变化 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,4)">排名变化 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,5)">战力变化 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,6)">胜率变化 <span class="sort-icon">↕</span></th>
  </tr></thead><tbody>`;

  const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
  diff.forEach(d => {
