function renderCompareCharts(diff) {
  const chartDefaults = getChartDefaults();

  // Chart 1: Score delta — top 10 risers + top 10 fallers
  const byScore = [...diff].sort((a, b) => b.scoreDelta - a.scoreDelta);
  const topRise = byScore.slice(0, 10);
  const topFall = byScore.slice(-10).reverse();

  const labels1 = [...topRise.map(d => '⬆ ' + d.name), ...topFall.map(d => '⬇ ' + d.name)];
  const data1 = [...topRise.map(d => d.scoreDelta), ...topFall.map(d => d.scoreDelta)];
  const bgColors1 = [
    ...topRise.map(() => 'rgba(63,185,80,0.7)'),
    ...topFall.map(() => 'rgba(248,81,73,0.7)')
  ];

  new Chart(document.getElementById('chartScoreDelta'), {
    type: 'bar',
    data: {
      labels: labels1,
      datasets: [{ label: '评分变化', data: data1, backgroundColor: bgColors1, borderRadius: 4 }]
    },
    options: {
      ...chartDefaults,
      indexAxis: 'y',
      plugins: { title: { display: true, text: '评分变化 Top 10 上升 / 下降', color: '#c9d1d9', font: { size: 14 } }, legend: { display: false } },
      scales: {
        x: { ...chartDefaults.scales.x, title: { display: true, text: '评分变化', color: '#8b949e' } },
        y: { ...chartDefaults.scales.y, ticks: { ...chartDefaults.scales.y.ticks, font: { size: 11 } } }
      }
    }
  });

  // Chart 2: Tier change counts
  const tierChangeCounts = { up: 0, down: 0, same: 0 };
  const tierOrder = ["T4", "T3", "T2", "T1", "T0.5", "T0"];
  diff.forEach(d => {
    const a = tierOrder.indexOf(d.tierA), b = tierOrder.indexOf(d.tierB);
    if (b > a) tierChangeCounts.up++;
    else if (b < a) tierChangeCounts.down++;
    else tierChangeCounts.same++;
  });

  new Chart(document.getElementById('chartTierChange'), {
    type: 'doughnut',
    data: {
      labels: ['梯度上升', '梯度下降', '梯度不变'],
      datasets: [{
        data: [tierChangeCounts.up, tierChangeCounts.down, tierChangeCounts.same],
        backgroundColor: ['rgba(63,185,80,0.8)', 'rgba(248,81,73,0.8)', 'rgba(139,148,158,0.6)'],
        borderColor: '#0d1117',
        borderWidth: 2
      }]
    },
    options: {
      ...chartDefaults,
      plugins: { title: { display: true, text: '梯度变化分布', color: '#c9d1d9', font: { size: 14 } }, legend: { position: 'bottom', labels: { color: '#c9d1d9', padding: 16 } } }
    }
  });
}

