// --- Tier migration matrix ---
function renderTierMatrix(diff) {
  const tiers = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
  // Build matrix: matrix[oldTier][newTier] = count
  const matrix = {};
  tiers.forEach(t => { matrix[t] = {}; tiers.forEach(u => { matrix[t][u] = 0; }); });

  diff.forEach(d => {
    matrix[d.tierA][d.tierB] = (matrix[d.tierA][d.tierB] || 0) + 1;
  });

  const colors = getTierColors();
  let html = `<h3 style="margin-bottom:8px;color:#c9d1d9;">🔄 梯度迁移矩阵</h3>
    <table class="tier-matrix"><thead><tr><th>旧梯度 ↓ / 新梯度 →</th>`;
  tiers.forEach(t => { html += `<th style="background:${colors[t]}33">${t}</th>`; });
  html += `<th>合计</th></tr></thead><tbody>`;

  tiers.forEach(tOld => {
    html += `<tr><th style="background:${colors[tOld]}33">${tOld}</th>`;
    let rowSum = 0;
    tiers.forEach(tNew => {
      const cnt = matrix[tOld][tNew];
      rowSum += cnt;
      let cellStyle = '';
      if (cnt > 0 && tOld !== tNew) {
        const oldIdx = tiers.indexOf(tOld), newIdx = tiers.indexOf(tNew);
        cellStyle = newIdx > oldIdx
          ? 'background:rgba(63,185,80,0.15);color:#3fb950;font-weight:600'
          : 'background:rgba(248,81,73,0.15);color:#f85149;font-weight:600';
      } else if (cnt > 0) {
        cellStyle = 'background:rgba(139,148,158,0.1)';
      }
      html += `<td style="${cellStyle}">${cnt > 0 ? cnt : ''}</td>`;
    });
    html += `<td style="font-weight:600">${rowSum}</td></tr>`;
  });
  html += '</tbody></table>';

