  // 版本对比按钮 (only when >=2 dates available)
  if (gameConfig.hasDates && gameConfig.dates && gameConfig.dates.length >= 2) {
    html += `<button id="btn-compare" onclick="switchToCompareMode()" style="margin-left:4px">📊 版本对比</button>`;
