// --- Compare table sorting ---
function sortCompareTable(th, colIdx) {
  const table = th.closest("table");
  const tbody = table.querySelector("tbody");
  const rows = Array.from(tbody.querySelectorAll("tr"));
  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");

  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
  th.classList.add("sorted");
  if (isDesc) th.classList.add("desc");

  // Extract data from each row
  const rowData = rows.map(row => {
    const cells = row.querySelectorAll("td");
    let val;
    switch (colIdx) {
      case 0: val = cells[0]?.textContent?.trim() || ''; break;
      case 1: val = cells[1]?.textContent?.trim() || ''; break;
      case 2: val = cells[2]?.textContent?.trim() || ''; break;
      default: val = parseFloat(cells[colIdx]?.textContent?.trim()) || 0;
    }
    return { row, val };
  });

  // Sort by tiers (T0 > T0.5 > T1 > T2 > T3 > T4)
  if (colIdx === 1 || colIdx === 2) {
    const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
    rowData.sort((a, b) => {
      const ia = tierOrder.indexOf(a.val), ib = tierOrder.indexOf(b.val);
      return isDesc ? ib - ia : ia - ib;
    });
  } else if (typeof rowData[0].val === 'number') {
    rowData.sort((a, b) => isDesc ? b.val - a.val : a.val - b.val);
  } else {
    rowData.sort((a, b) => isDesc ? b.val.localeCompare(a.val) : a.val.localeCompare(b.val));
  }

  rowData.forEach(d => tbody.appendChild(d.row));
}

// --- Compare table filtering ---
function filterCompareTable(query) {
  const table = document.querySelector(".compare-table");
  if (!table) return;
  const rows = table.querySelectorAll("tbody tr");
  const q = query.trim().toLowerCase();
  rows.forEach(row => {
    const nameCell = row.querySelector(".hero-name");
    const name = nameCell ? nameCell.textContent.toLowerCase() : "";
    row.style.display = (!q || name.includes(q)) ? "" : "none";
  });
}

