/* 对比模式头部 */
.compare-header {
    display: flex; align-items: center; gap: 16px;
    padding: 16px 20px;
    background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
    border-bottom: 1px solid #30363d;
    margin-bottom: 16px;
}
.compare-header h2 { font-size: 1.2rem; color: #f0f6fc; flex: 1; margin: 0; }
.exit-compare-btn {
    padding: 6px 16px; border: 1px solid #f85149; border-radius: 6px;
    background: transparent; color: #f85149; cursor: pointer;
    font-size: 13px; font-family: inherit;
}
.exit-compare-btn:hover { background: rgba(248,81,73,0.15); }

/* 对比摘要卡片 */
.compare-summary { margin-bottom: 16px; }

/* 差异颜色 */
.diff-positive { color: #3fb950 !important; }
.diff-negative { color: #f85149 !important; }
.diff-neutral  { color: #8b949e !important; }

/* 梯度变化箭头 */
.tier-up   { color: #3fb950; font-size: 0.8em; margin-left: 2px; }
.tier-down { color: #f85149; font-size: 0.8em; margin-left: 2px; }

/* 对比表格 */
.compare-table { width: 100%; }
.compare-table thead th {
    cursor: pointer; user-select: none;
    padding: 10px 12px; font-size: 0.8rem;
    color: #8b949e; text-align: left;
    border-bottom: 2px solid #30363d;
    white-space: nowrap;
}
.compare-table thead th:hover { color: #58a6ff; }
.compare-table thead th .sort-icon { font-size: 0.65rem; margin-left: 4px; opacity: 0.5; }
.compare-table thead th.sorted .sort-icon { opacity: 1; color: #58a6ff; }
.compare-table tbody td {
    padding: 8px 12px; font-size: 0.85rem;
    border-bottom: 1px solid #21262d;
    white-space: nowrap;
}
.compare-table tbody tr:hover { background: #1c2129; }

/* 新增/移除英雄提示 */
.compare-removed {
    padding: 10px 16px; margin: 0 16px 12px;
    background: rgba(139,148,158,0.08); border-radius: 6px;
    font-size: 0.85rem; line-height: 1.8;
}

/* 图表容器 */
.chart-row {
    display: flex; gap: 16px; margin: 16px; flex-wrap: wrap;
}
.chart-container {
    flex: 1; min-width: 400px;
    background: #161b22; border: 1px solid #30363d;
    border-radius: 8px; padding: 20px;
}
.chart-container canvas { max-height: 420px; }
.chart-wide { flex: 1 1 100%; min-width: 0; }

/* 梯度迁移矩阵 */
.tier-matrix {
    width: 100%; border-collapse: collapse;
    margin-top: 8px; font-size: 0.85rem;
}
.tier-matrix thead th,
.tier-matrix tbody th {
    padding: 8px 12px; text-align: center;
    border: 1px solid #30363d; font-weight: 600;
}
.tier-matrix tbody td {
    padding: 8px 12px; text-align: center;
    border: 1px solid #21262d;
    min-width: 48px;
}
.tier-matrix tbody tr:hover td { background: rgba(88,166,255,0.05); }

