    fetch(base + "/" + entryA.file),
    fetch(base + "/" + entryB.file)
  ]);
  if (!respA.ok || !respB.ok) throw new Error("加载对比数据失败");
  const rawA = await respA.json();
  const rawB = await respB.json();
  // Run computeSG independently on each dataset
  const resultA = computeSG(rawA);
  const resultB = computeSG(rawB);
  return computeDiff(resultA, resultB);
}

function computeDiff(resultA, resultB) {
  const mapA = new Map(resultA.heroes.map(h => [h.name, h]));
  const mapB = new Map(resultB.heroes.map(h => [h.name, h]));
  const diff = [];
  const onlyInA = [];
  const onlyInB = [];

  for (const [name, heroB] of mapB) {
    const heroA = mapA.get(name);
    if (!heroA) { onlyInB.push(heroB); continue; }
    diff.push({
      name,
      headIcon: heroB.headIcon,
      tierA: heroA.tier, tierB: heroB.tier,
      rankA: heroA.rank, rankB: heroB.rank,
      scoreA: heroA.score, scoreB: heroB.score,
      scoreDelta: heroB.score - heroA.score,
      combatPowerA: heroA.combatPower, combatPowerB: heroB.combatPower,
      combatPowerDelta: heroB.combatPower - heroA.combatPower,
      winRateA: heroA.winRate, winRateB: heroB.winRate,
      winRateDelta: (heroB.winRate - heroA.winRate) * 100, // in percentage points
      appearanceRankA: heroA.appearanceRank, appearanceRankB: heroB.appearanceRank,
      appearanceRankDelta: heroA.appearanceRank - heroB.appearanceRank, // positive = rose
      rankDelta: heroA.rank - heroB.rank, // positive = rose in ranking
      tierChanged: heroA.tier !== heroB.tier
    });
  }

  for (const [name, heroA] of mapA) {
    if (!mapB.has(name)) onlyInA.push(heroA);
  }

  // Sort by absolute scoreDelta descending (biggest changes first)
  diff.sort((a, b) => Math.abs(b.scoreDelta) - Math.abs(a.scoreDelta));
  return { diff, onlyInA, onlyInB };
}

function renderCompareView(result, dateA, dateB) {
  const { diff, onlyInA, onlyInB } = result;

  // --- Summary stats ---
  const tierUp = diff.filter(d => {
    const order = ["T4","T3","T2","T1","T0.5","T0"];
    return order.indexOf(d.tierB) > order.indexOf(d.tierA);
  }).length;
  const tierDown = diff.filter(d => {
    const order = ["T4","T3","T2","T1","T0.5","T0"];
    return order.indexOf(d.tierB) < order.indexOf(d.tierA);
  }).length;
  const tierSame = diff.length - tierUp - tierDown;
  const avgScoreDelta = diff.reduce((s, d) => s + d.scoreDelta, 0) / diff.length;
  const biggestRiser = diff.reduce((best, d) => d.rankDelta > best.rankDelta ? d : best, diff[0]);
  const biggestFaller = diff.reduce((best, d) => d.rankDelta < best.rankDelta ? d : best, diff[0]);

  let html = '';

  // Compare header
  html += `<div class="compare-header">
    <h2>📊 版本对比：${dateA} → ${dateB}</h2>
    <button class="exit-compare-btn" onclick="exitCompareMode()">✕ 退出对比</button>
  </div>`;

  // Summary stat cards
  html += `<div class="stats-row compare-summary">
    <div class="stat-card"><div class="stat-value diff-positive">⬆ ${tierUp}</div><div class="stat-label">梯度上升</div></div>
    <div class="stat-card"><div class="stat-value diff-negative">⬇ ${tierDown}</div><div class="stat-label">梯度下降</div></div>
    <div class="stat-card"><div class="stat-value">${tierSame}</div><div class="stat-label">梯度不变</div></div>
    <div class="stat-card"><div class="stat-value ${avgScoreDelta >= 0 ? 'diff-positive' : 'diff-negative'}">${avgScoreDelta >= 0 ? '+' : ''}${avgScoreDelta.toFixed(1)}</div><div class="stat-label">平均评分变化</div></div>
    <div class="stat-card"><div class="stat-value diff-positive">🏆 ${biggestRiser.name}<br><small>+${biggestRiser.rankDelta} 名</small></div><div class="stat-label">最大升幅</div></div>
    <div class="stat-card"><div class="stat-value diff-negative">📉 ${biggestFaller.name}<br><small>${biggestFaller.rankDelta} 名</small></div><div class="stat-label">最大降幅</div></div>
  </div>`;

  // New/removed heroes
  if (onlyInA.length > 0 || onlyInB.length > 0) {
    html += `<div class="compare-removed">`;
    if (onlyInA.length > 0) html += `<span class="diff-negative">⚠️ 仅存在于 ${dateA} (已移除): ${onlyInA.map(h => h.name).join('、')}</span> `;
    if (onlyInB.length > 0) html += `<span class="diff-positive">🆕 仅存在于 ${dateB} (新增): ${onlyInB.map(h => h.name).join('、')}</span>`;
    html += `</div>`;
  }

  // --- Diff Table ---
  html += `<div class="table-wrapper"><table class="compare-table"><thead><tr>
    <th onclick="sortCompareTable(this,0)">英雄 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,1)">${dateA} 梯度 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,2)">${dateB} 梯度 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,3)">评分变化 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,4)">排名变化 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,5)">战力变化 <span class="sort-icon">↕</span></th>
    <th onclick="sortCompareTable(this,6)">胜率变化 <span class="sort-icon">↕</span></th>
  </tr></thead><tbody>`;

  const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
  diff.forEach(d => {
    const tierArrow = d.tierChanged
      ? (tierOrder.indexOf(d.tierB) > tierOrder.indexOf(d.tierA)
          ? '<span class="tier-up">▲</span>' : '<span class="tier-down">▼</span>')
      : '';
    const scoreCls = d.scoreDelta > 0.5 ? 'diff-positive' : d.scoreDelta < -0.5 ? 'diff-negative' : 'diff-neutral';
    const rankCls = d.rankDelta > 0 ? 'diff-positive' : d.rankDelta < 0 ? 'diff-negative' : 'diff-neutral';
    const cpCls = d.combatPowerDelta > 0 ? 'diff-positive' : d.combatPowerDelta < 0 ? 'diff-negative' : 'diff-neutral';
    const wrCls = d.winRateDelta > 0.1 ? 'diff-positive' : d.winRateDelta < -0.1 ? 'diff-negative' : 'diff-neutral';

    html += `<tr>
      <td><div class="hero-cell"><img class="hero-icon" src="${d.headIcon || ''}" alt="${d.name}" onerror="this.style.display='none'"> <span class="hero-name">${d.name}</span></div></td>
      <td>${getTierBadge(d.tierA)}</td>
      <td>${getTierBadge(d.tierB)} ${tierArrow}</td>
      <td class="${scoreCls}">${d.scoreDelta >= 0 ? '+' : ''}${d.scoreDelta.toFixed(1)}</td>
      <td class="${rankCls}">${d.rankDelta > 0 ? '+' : ''}${d.rankDelta}</td>
      <td class="${cpCls}">${d.combatPowerDelta >= 0 ? '+' : ''}${d.combatPowerDelta}</td>
      <td class="${wrCls}">${d.winRateDelta >= 0 ? '+' : ''}${d.winRateDelta.toFixed(2)}%</td>
    </tr>`;
  });
  html += `</tbody></table></div>`;

  // --- Charts ---
  if (typeof Chart !== 'undefined') {
    html += `<div class="chart-row">
      <div class="chart-container"><canvas id="chartScoreDelta"></canvas></div>
      <div class="chart-container"><canvas id="chartTierChange"></canvas></div>
    </div>`;
    html += `<div class="chart-row">
      <div class="chart-container chart-wide">${renderTierMatrix(diff)}</div>
    </div>`;

    // Schedule chart rendering after DOM update
    setTimeout(() => renderCompareCharts(diff), 50);
  }

  return html;
}

// Exit compare mode
function exitCompareMode() {
  currentViewMode = "table";
  buildControls();
  renderAll();
}

// --- Tier migration matrix ---
function renderTierMatrix(diff) {
  const tiers = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
  // Build matrix: matrix[oldTier][newTier] = count
  const matrix = {};
  tiers.forEach(t => { matrix[t] = {}; tiers.forEach(u => { matrix[t][u] = 0; }); });

  diff.forEach(d => {
    matrix[d.tierA][d.tierB] = (matrix[d.tierA][d.tierB] || 0) + 1;
  });

  const colors = getTierColors();
  let html = `<h3 style="margin-bottom:8px;color:#c9d1d9;">🔄 梯度迁移矩阵</h3>
    <table class="tier-matrix"><thead><tr><th>旧梯度 ↓ / 新梯度 →</th>`;
  tiers.forEach(t => { html += `<th style="background:${colors[t]}33">${t}</th>`; });
  html += `<th>合计</th></tr></thead><tbody>`;

  tiers.forEach(tOld => {
    html += `<tr><th style="background:${colors[tOld]}33">${tOld}</th>`;
    let rowSum = 0;
    tiers.forEach(tNew => {
      const cnt = matrix[tOld][tNew];
      rowSum += cnt;
      let cellStyle = '';
      if (cnt > 0 && tOld !== tNew) {
        const oldIdx = tiers.indexOf(tOld), newIdx = tiers.indexOf(tNew);
        cellStyle = newIdx > oldIdx
          ? 'background:rgba(63,185,80,0.15);color:#3fb950;font-weight:600'
          : 'background:rgba(248,81,73,0.15);color:#f85149;font-weight:600';
      } else if (cnt > 0) {
        cellStyle = 'background:rgba(139,148,158,0.1)';
      }
      html += `<td style="${cellStyle}">${cnt > 0 ? cnt : ''}</td>`;
    });
    html += `<td style="font-weight:600">${rowSum}</td></tr>`;
  });
  html += '</tbody></table>';
  return html;
}

// --- Chart.js rendering ---
function renderCompareCharts(diff) {
  const chartDefaults = getChartDefaults();

  // Chart 1: Score delta — top 10 risers + top 10 fallers
  const byScore = [...diff].sort((a, b) => b.scoreDelta - a.scoreDelta);
  const topRise = byScore.slice(0, 10);
  const topFall = byScore.slice(-10).reverse();

  const labels1 = [...topRise.map(d => '⬆ ' + d.name), ...topFall.map(d => '⬇ ' + d.name)];
  const data1 = [...topRise.map(d => d.scoreDelta), ...topFall.map(d => d.scoreDelta)];
  const bgColors1 = [
    ...topRise.map(() => 'rgba(63,185,80,0.7)'),
    ...topFall.map(() => 'rgba(248,81,73,0.7)')
  ];

  new Chart(document.getElementById('chartScoreDelta'), {
    type: 'bar',
    data: {
      labels: labels1,
      datasets: [{ label: '评分变化', data: data1, backgroundColor: bgColors1, borderRadius: 4 }]
    },
    options: {
      ...chartDefaults,
      indexAxis: 'y',
      plugins: { title: { display: true, text: '评分变化 Top 10 上升 / 下降', color: '#c9d1d9', font: { size: 14 } }, legend: { display: false } },
      scales: {
        x: { ...chartDefaults.scales.x, title: { display: true, text: '评分变化', color: '#8b949e' } },
        y: { ...chartDefaults.scales.y, ticks: { ...chartDefaults.scales.y.ticks, font: { size: 11 } } }
      }
    }
  });

  // Chart 2: Tier change counts
  const tierChangeCounts = { up: 0, down: 0, same: 0 };
  const tierOrder = ["T4", "T3", "T2", "T1", "T0.5", "T0"];
  diff.forEach(d => {
    const a = tierOrder.indexOf(d.tierA), b = tierOrder.indexOf(d.tierB);
    if (b > a) tierChangeCounts.up++;
    else if (b < a) tierChangeCounts.down++;
    else tierChangeCounts.same++;
  });

  new Chart(document.getElementById('chartTierChange'), {
    type: 'doughnut',
    data: {
      labels: ['梯度上升', '梯度下降', '梯度不变'],
      datasets: [{
        data: [tierChangeCounts.up, tierChangeCounts.down, tierChangeCounts.same],
        backgroundColor: ['rgba(63,185,80,0.8)', 'rgba(248,81,73,0.8)', 'rgba(139,148,158,0.6)'],
        borderColor: '#0d1117',
        borderWidth: 2
      }]
    },
    options: {
      ...chartDefaults,
      plugins: { title: { display: true, text: '梯度变化分布', color: '#c9d1d9', font: { size: 14 } }, legend: { position: 'bottom', labels: { color: '#c9d1d9', padding: 16 } } }
    }
  });
}

function getChartDefaults() {
  return {
    responsive: true,
    maintainAspectRatio: true,
    backgroundColor: 'transparent',
    plugins: { legend: { labels: { color: '#c9d1d9' } } },
    scales: {
      x: { ticks: { color: '#8b949e' }, grid: { color: '#21262d' } },
      y: { ticks: { color: '#8b949e' }, grid: { color: '#21262d' } }
    }
  };
}

// --- Compare table sorting ---
function sortCompareTable(th, colIdx) {
  const table = th.closest("table");
  const tbody = table.querySelector("tbody");
  const rows = Array.from(tbody.querySelectorAll("tr"));
  const isDesc = th.classList.contains("sorted") && !th.classList.contains("desc");

  table.querySelectorAll("th").forEach(h => { h.classList.remove("sorted", "desc"); });
  th.classList.add("sorted");
  if (isDesc) th.classList.add("desc");

  // Extract data from each row
  const rowData = rows.map(row => {
    const cells = row.querySelectorAll("td");
    let val;
    switch (colIdx) {
      case 0: val = cells[0]?.textContent?.trim() || ''; break;
      case 1: val = cells[1]?.textContent?.trim() || ''; break;
      case 2: val = cells[2]?.textContent?.trim() || ''; break;
      default: val = parseFloat(cells[colIdx]?.textContent?.trim()) || 0;
    }
    return { row, val };
  });

  // Sort by tiers (T0 > T0.5 > T1 > T2 > T3 > T4)
  if (colIdx === 1 || colIdx === 2) {
    const tierOrder = ["T0", "T0.5", "T1", "T2", "T3", "T4"];
    rowData.sort((a, b) => {
      const ia = tierOrder.indexOf(a.val), ib = tierOrder.indexOf(b.val);
      return isDesc ? ib - ia : ia - ib;
    });
  } else if (typeof rowData[0].val === 'number') {
    rowData.sort((a, b) => isDesc ? b.val - a.val : a.val - b.val);
  } else {
    rowData.sort((a, b) => isDesc ? b.val.localeCompare(a.val) : a.val.localeCompare(b.val));
  }

  rowData.forEach(d => tbody.appendChild(d.row));
}

// --- Compare table filtering ---
function filterCompareTable(query) {
  const table = document.querySelector(".compare-table");
  if (!table) return;
  const rows = table.querySelectorAll("tbody tr");
  const q = query.trim().toLowerCase();
  rows.forEach(row => {
    const nameCell = row.querySelector(".hero-name");
    const name = nameCell ? nameCell.textContent.toLowerCase() : "";
    row.style.display = (!q || name.includes(q)) ? "" : "none";
  });
}

