const wrVals = heroes.map(h => h.winRate);
const wrMin = Math.min(...wrVals), wrMax = Math.max(...wrVals), wrRange = wrMax - wrMin || 1;
const wrScores = wrVals.map(v => (v - wrMin) / wrRange);
heroes.forEach((h, i) => {
  h.raw_weighted = weights.appearance * appearanceScores[i] + weights.combat * combatScores[i] + weights.winrate * wrScores[i];
